//这里对移动图形函数进行的优化，使得移动图形的时候不能够移出图片区域
function move_draw(list, ctx, cav, index, sX, sY) {
   let mark = list[index];
   let handle_move = em => {
      let target_data = [];
      let newX = em.offsetX - sX;
      let newY = em.offsetY - sY;

      // 边界检查，确保图形不会移出canvas
      mark.forEach(item => {
         let calculatedX = item.x + newX;
         let calculatedY = item.y + newY;

         // 限制calculatedX和calculatedY在canvas范围内
         calculatedX = Math.max(0, Math.min(cav.width, calculatedX));
         calculatedY = Math.max(0, Math.min(cav.height, calculatedY));

         target_data.push({
            x: calculatedX,
            y: calculatedY,
         });
      });

      ctx.clearRect(0, 0, cav.width, cav.height); // 使用cav.width和cav.height而不是固定值
      list.splice(index, 1, target_data);
      draw_all_lines(list, ctx);
      draw_all_circles(list, ctx);
      fillarea(list, ctx, index);
   };

   let handle_up = e => {
      cav.removeEventListener('mousemove', handle_move);
      cav.removeEventListener('mouseup', handle_up);
   };

   // 移除监听器部分保持不变
   cav.removeEventListener('mousemove', handle_move) // 先移除监听
   cav.removeEventListener('mousemove', handle_move) // 先移除监听
   cav.removeEventListener('mouseup', handle_up) // 先移除监听
   cav.removeEventListener('mouseup', handle_up) // 先移除监听
   cav.removeEventListener('mousemove', handle_move) // 先移除监听
   cav.removeEventListener('mousemove', handle_move) // 先移除监听
   cav.removeEventListener('mouseup', handle_up) // 先移除监听
   cav.removeEventListener('mouseup', handle_up) // 先移除监听
   cav.addEventListener('mousemove', handle_move) // 再重新监听，解决点击多次移除不干净的bug
   cav.addEventListener('mouseup', handle_up) // 再重新监听，解决点击多次移除不干净的bug
}

/* 编辑多边形端点 */
function changeDraw(list, cav, ctx, index_list) {
   cav.style.cursor = 'pointer'
}

// 判断鼠标是否在端点
function findClosestPointIndex(list, points, type) {
   let closestIndex = []
   let closestDistance = Infinity
   for (let i = 0; i < list.length; i++) {
      for (let j = 0; j < list[i].length; j++) {
         let point = list[i][j]
         let diffX = Math.abs(points.x - point.x)
         let diffY = Math.abs(points.y - point.y)
         let distance = Math.sqrt(diffX * diffX + diffY * diffY)
         if (distance <= 2 && distance < closestDistance) {
            closestIndex = [i, j]
            closestDistance = distance
         }
      }
   }
   if (type == 'is') return closestIndex.length
   return closestIndex
}

// 清除当前未画完成的区域
function clear_now_line(list, ctx) {
   ctx.clearRect(0, 0, 800, 600)
   if (list.length != 0) {
      draw_all_lines(list, ctx)
      draw_all_circles(list, ctx)
      fillarea(list, ctx)
   }
}

// 绘制选中的,颜色填充
function fillarea(list, ctx, index) {
   for (var i = 0; i < list.length; i++) {
      var cors = list[i]
      var x0 = cors[0].x
      var y0 = cors[0].y
      ctx.beginPath()
      ctx.fillStyle = i == index ? 'rgba(255,0,0,0.1)' : 'transparent'
      ctx.moveTo(x0, y0)
      for (var j = 1; j < cors.length; j++) {
         var x = cors[j].x
         var y = cors[j].y
         ctx.lineTo(x, y)
      }
      ctx.fill()
      ctx.closePath()
   }
}

// 判断坐标点是否在区域内的函数
function isPointInPolygon(list, point) {
   let isInside = false
   // 射线与多边形边线的交点数量
   let intersections = 0
   for (let i = 0; i < list.length; i++) {
      let coordinate1 = list[i]
      let coordinate2 = list[(i + 1) % list.length]
      // 判断射线与边线是否相交
      if (
         coordinate1.y > point.y !== coordinate2.y > point.y &&
         point.x <
         ((coordinate2.x - coordinate1.x) * (point.y - coordinate1.y)) /
         (coordinate2.y - coordinate1.y) +
         coordinate1.x
      ) {
         intersections++
      }
   }
   // 判断点是否在多边形内
   if (intersections % 2 !== 0) {
      isInside = true
   }
   return isInside
}

// 把当前绘制的多边形之前的坐标线段绘制出来
function draw_now_line(coordinates, ctx) {
   for (let i = 0; i < coordinates.length - 1; i++) {
      ctx.beginPath()
      let x0 = coordinates[i].x
      let y0 = coordinates[i].y
      let x1 = coordinates[i + 1].x
      let y1 = coordinates[i + 1].y
      ctx.moveTo(x0, y0)
      ctx.lineTo(x1, y1)
      ctx.stroke()
      ctx.closePath()
   }
}

// 把当前绘制的多边形之前的端点画圆
function draw_now_circle(coordinates, ctx) {
   ctx.fillStyle = 'red'
   for (let i = 0; i < coordinates.length; i++) {
      let x = coordinates[i].x
      let y = coordinates[i].y
      ctx.beginPath() //起始一条路径，或重置当前路径
      ctx.moveTo(x, y) //把路径移动到画布中的指定点（x,y）开始坐标
      ctx.arc(x, y, 5, 0, Math.PI * 2) //点
      ctx.fill() //填充点
      ctx.closePath() //创建从当前点回到起始点的路径
   }
}

// 画出所有多边形
function draw_all_lines(list, ctx) {
   for (let i = 0; i < list.length; i++) {
      let cors = list[i]
      //前后坐标连线
      for (let j = 0; j < cors.length - 1; j++) {
         ctx.beginPath()
         let x0 = cors[j].x
         let y0 = cors[j].y
         let x1 = cors[j + 1].x
         let y1 = cors[j + 1].y
         ctx.moveTo(x0, y0)
         ctx.lineTo(x1, y1)
         ctx.stroke()
         ctx.closePath()
      }
      //最后一个与第一个连线
      let begin_x = cors[0].x
      let begin_y = cors[0].y
      let end_x = cors[cors.length - 1].x
      let end_y = cors[cors.length - 1].y
      ctx.fillStyle = 'transparent'
      ctx.beginPath()
      ctx.moveTo(begin_x, begin_y)
      ctx.lineTo(end_x, end_y)
      ctx.stroke()
      ctx.closePath()
   }
}

// 画出所有多边形的端点
function draw_all_circles(list, ctx, cav) {
   ctx.fillStyle = 'red'
   for (let i = 0; i < list.length; i++) {
      let cors = list[i]
      for (let j = 0; j < cors.length; j++) {
         let x = cors[j].x
         let y = cors[j].y
         ctx.beginPath()
         ctx.moveTo(x, y)
         ctx.arc(x, y, 4, 0, Math.PI * 2)
         ctx.fill()
         ctx.closePath()
      }
   }
}

// 判断直线是否相交
function judgeIntersect(x1, y1, x2, y2, x3, y3, x4, y4) {
   if (
      !(
         Math.min(x1, x2) <= Math.max(x3, x4) &&
         Math.min(y3, y4) <= Math.max(y1, y2) &&
         Math.min(x3, x4) <= Math.max(x1, x2) &&
         Math.min(y1, y2) <= Math.max(y3, y4)
      )
   )
      return false
   let u, v, w, z
   u = (x3 - x1) * (y2 - y1) - (x2 - x1) * (y3 - y1)
   v = (x4 - x1) * (y2 - y1) - (x2 - x1) * (y4 - y1)
   w = (x1 - x3) * (y4 - y3) - (x4 - x3) * (y1 - y3)
   z = (x2 - x3) * (y4 - y3) - (x4 - x3) * (y2 - y3)
   return u * v <= 0.00000001 && w * z <= 0.00000001
}