/**
 * 绘制不规则多边形，只用于回显，不需要标点功能的地方，表格
 */

// import { Message } from 'element-ui'

export function draw_test2(cav, list) {
   // 画布初始化
   let ctx = cav.getContext('2d')
   ctx.strokeStyle = 'red'
   ctx.lineWidth = 2
   cav.style.cursor = 'default'; // 或其他样式
   // 变量初始化
   // let isDrawingCompleted = false   //只允许绘制一个图形
   // let isdraw = false // 是否在画图形
   // let endtip = false // 是否结束一个多边形的绘制
   // let coordinates = [] // 一个多边形信息
   // let point_in_area = false // 鼠标是否在区域内
   // let target_index = null // 目标索引
   // let is_select = false // 是否选中某个区域
   // let index_list = [] // 是否选中某个端点
   // let is_click = false // 是否按下鼠标
   // let click_point = {} // 按下鼠标的坐标
   // 初始判断是否有框
   // draw_now_line(coordinates, ctx) // 把之前的点连线
   // draw_now_circle(coordinates, ctx) //画之前的点
   if (list.length != 0) {
      // 画所有的
      draw_all_lines(list, ctx)
      draw_all_circles(list, ctx)
      fillarea(list, ctx)
   }
}

// 绘制选中的,颜色填充
function fillarea(list, ctx, index) {
   for (var i = 0; i < list.length; i++) {
      var cors = list[i]
      var x0 = cors[0].x
      var y0 = cors[0].y
      ctx.beginPath()
      ctx.fillStyle = i == index ? 'rgba(255,0,0,0.1)' : 'transparent'
      ctx.moveTo(x0, y0)
      for (var j = 1; j < cors.length; j++) {
         var x = cors[j].x
         var y = cors[j].y
         ctx.lineTo(x, y)
      }
      ctx.fill()
      ctx.closePath()
   }
}

// 把当前绘制的多边形之前的坐标线段绘制出来
function draw_now_line(coordinates, ctx) {
   for (let i = 0; i < coordinates.length - 1; i++) {
      ctx.beginPath()
      let x0 = coordinates[i].x
      let y0 = coordinates[i].y
      let x1 = coordinates[i + 1].x
      let y1 = coordinates[i + 1].y
      ctx.moveTo(x0, y0)
      ctx.lineTo(x1, y1)
      ctx.stroke()
      ctx.closePath()
   }
}

// 画出所有多边形
function draw_all_lines(list, ctx) {
   for (let i = 0; i < list.length; i++) {
      let cors = list[i]
      ctx.strokeStyle = cors[0].color
      //前后坐标连线
      for (let j = 0; j < cors.length - 1; j++) {
         ctx.beginPath()
         let x0 = cors[j].x
         let y0 = cors[j].y
         let x1 = cors[j + 1].x
         let y1 = cors[j + 1].y
         ctx.moveTo(x0, y0)
         ctx.lineTo(x1, y1)
         ctx.stroke()
         ctx.closePath()
      }
      //最后一个与第一个连线
      let begin_x = cors[0].x
      let begin_y = cors[0].y
      let end_x = cors[cors.length - 1].x
      let end_y = cors[cors.length - 1].y
      ctx.fillStyle = 'transparent'
      ctx.beginPath()
      ctx.moveTo(begin_x, begin_y)
      ctx.lineTo(end_x, end_y)
      ctx.stroke()
      ctx.closePath()
   }
   ctx.strokeStyle = 'red'
}

// 画出所有多边形的端点
function draw_all_circles(list, ctx, cav) {
   for (let i = 0; i < list.length; i++) {
      let cors = list[i]
      ctx.fillStyle = cors[0].color
      for (let j = 0; j < cors.length; j++) {
         let x = cors[j].x
         let y = cors[j].y
         ctx.beginPath()
         ctx.moveTo(x, y)
         ctx.arc(x, y, 4, 0, Math.PI * 2)
         ctx.fill()
         ctx.closePath()
      }
   }
   ctx.fillStyle = 'red'
}