/**
 * 绘制不规则多边形，全功能。画线
 */

import { Message } from 'element-ui'
export function draw_test(cav, list, callback, coordinates) {
   // console.log("???????", list);
   // 画布初始化
   let ctx = cav.getContext('2d')
   ctx.strokeStyle = 'red'
   ctx.lineWidth = 2

   // 变量初始化
   // let isDrawingCompleted = false   //只允许绘制一个图形
   // if(list.length>0){
   //    isDrawingCompleted=true
   // }
   let isdraw = false // 是否在画图形
   let endtip = false // 是否结束一个多边形的绘制
   // let coordinates = [] // 一个多边形信息
   let point_in_area = false // 鼠标是否在区域内，区域内限制开关
   let target_index = null // 目标索引
   let is_select = false // 是否选中某个区域
   let index_list = [] // 是否选中某个端点
   let is_click = false // 是否按下鼠标
   let click_point = {} // 按下鼠标的坐标
   // 初始判断是否有框
   draw_now_line(coordinates, ctx) // 把之前的点连线
   draw_now_circle(coordinates, ctx) //画之前的点
   if (list.length != 0) {
      // 画所有的
      draw_all_lines(list, ctx)
      draw_all_circles(list, ctx)
      fillarea(list, ctx)
   }

   //  鼠标按下
   cav.onmousedown = e => {
      handleCanvasClick(e,list)
      if (e.which == 3) return
      let x = e.offsetX
      let y = e.offsetY
      //   是否在端点
      index_list = findClosestPointIndex(list, { x, y })
      if (index_list.length) {
         console.log('在端点')
         click_point = { x, y }
         is_click = true
         return
      }
      // 是否在区域内
      // if (point_in_area) {
      //    ctx.clearRect(0, 0, 800, 600)
      //    draw_all_lines(list, ctx)
      //    draw_all_circles(list, ctx)
      //    fillarea(list, ctx, target_index)
      //    is_select = true
      //    move_draw(list, ctx, cav, target_index, x, y)
      //    return
      // }
      is_select = false
      // if (isDrawingCompleted) {
      //    return
      // }
      if (endtip) {
         if (list.length < 10) {
            endtip = false //清空，重新画
         } else {
            Message.warning('最多可绘制20个闭合的凸多边形区域')
            return
         }
      }
      //获取鼠标按下的坐标，放入数组中
      let insertFlag = true
      coordinates.forEach((item, index) => {
         if (item.x == x && item.y == y) {
            insertFlag = false
         }
      })
      if (insertFlag) {
         coordinates.push({ x: x, y: y })
         // 判断相交
         let lineList = []
         coordinates.forEach((item, index) => {
            if (index < coordinates.length - 1) {
               lineList.push([item.x, item.y, coordinates[index + 1].x, coordinates[index + 1].y])
            }
         })
         lineList.forEach((item, index) => {
            if (index > 0 && index < lineList.length - 1) {
               let flag = judgeIntersect(
                  lineList[lineList.length - 1][0],
                  lineList[lineList.length - 1][1],
                  lineList[lineList.length - 1][2],
                  lineList[lineList.length - 1][3],
                  lineList[index - 1][0],
                  lineList[index - 1][1],
                  lineList[index - 1][2],
                  lineList[index - 1][3]
               )
               if (flag) {
                  coordinates.pop()
               }
            }
         })
      }
      draw_now_circle(coordinates, ctx)
      fillarea(list, ctx)
      isdraw = true //正在画多边形
   }

   // 鼠标抬起
   cav.onmouseup = e => {
      console.log(e)
      is_click = false
      click_point = {}
      index_list = []
      console.log(point_in_area)
      if (point_in_area) return
      target_index = null
      ctx.clearRect(0, 0, 800, 600) //清空画布
      draw_now_line(coordinates, ctx) //把之前的点连线
      draw_now_circle(coordinates, ctx) //画之前的点
      if (list.length != 0) {
         draw_all_lines(list, ctx)
         draw_all_circles(list, ctx)
         fillarea(list, ctx)
      }
   }

   // 鼠标移动
   cav.onmousemove = e => {
      // 判断是否移动到某个区域内
      let x = e.offsetX
      let y = e.offsetY
      // 判断是否在某个区域内
      let point = { x, y }
      if (list.length) {
         for (let i = 0; i < list.length; i++) {
            // point_in_area = isPointInPolygon(list[i], point)
            // if (point_in_area) {
            target_index = i
            // break
            // }
         }
         // cav.style.cursor = point_in_area ? 'move' : 'crosshair'
         cav.style.cursor = 'crosshair'
      } else {
         point_in_area = false
         ctx.clearRect(0, 0, 800, 600) //清空画布
         cav.style.cursor = 'crosshair'
      }
      if (point_in_area) {
         // console.log(point_in_area, target_index)
      } else {
         is_select = false
         target_index = null
         ctx.clearRect(0, 0, 800, 600)
         draw_all_lines(list, ctx)
         draw_all_circles(list, ctx)
         fillarea(list, ctx)
      }
      // 编辑端点判断是否在端点时点击并移动
      if (list.length) {
         // list_index 局部变量
         let list_index = findClosestPointIndex(list, point)
         if (list_index.length) changeDraw(list, cav, ctx, list_index)
         // index_list 全局变量
         if (index_list.length) {
            let target_data = {
               x: click_point.x + (x - click_point.x),
               y: click_point.y + (y - click_point.y),
               type: list[index_list[0]][0].type,
               color: list[index_list[0]][0].color
            }
            list[index_list[0]].splice(index_list[1], 1, target_data)
            return
         }
      }
      index_list = []
      is_click = false
      click_point = {}
      //没开始画或者结束画之后不进行操作
      if (coordinates.length == 0 || !isdraw || endtip) {
         return
      }
      //获取上一个点
      let last_x = coordinates[coordinates.length - 1].x
      let last_y = coordinates[coordinates.length - 1].y
      ctx.clearRect(0, 0, 800, 600) //清空画布
      draw_now_line(coordinates, ctx) //把之前的点连线
      draw_now_circle(coordinates, ctx) //画之前的点
      if (list.length != 0) {
         draw_all_lines(list, ctx)
         draw_all_circles(list, ctx)
         fillarea(list, ctx)
      }
      //获取鼠标移动时的点，画线，实现线段跟踪效果。
      ctx.beginPath()
      ctx.moveTo(last_x, last_y)
      ctx.lineTo(x, y) //追踪鼠标
      ctx.stroke() //绘制已定义的路径 追踪鼠标
      ctx.closePath()
   }

   // 鼠标双击
   cav.ondblclick = e => {
      // if (point_in_area) return  //区域内限制开关
      // if (isDrawingCompleted) return Message.warning('已经绘制完成！')
      if (coordinates.length <= 2) return
      // Message.warning('至少需要三个点，请继续绘制')
      // 这里需要对双击之后的点位进行判断同样不能出现两个点位相交的情况
      //双击画布，在最后一个点的时候双击，自动连线第一个点，同时宣告画结束
      let x0 = coordinates[0].x
      let y0 = coordinates[0].y
      let x1 = coordinates[coordinates.length - 1].x
      let y1 = coordinates[coordinates.length - 1].y
      ctx.beginPath()
      ctx.moveTo(x0, y0)
      ctx.lineTo(x1, y1)
      ctx.stroke()
      ctx.closePath()
      isdraw = false
      endtip = true
      list.push(coordinates)
      ctx.fillStyle = 'transparent'
      let bx = coordinates[0].x
      let by = coordinates[0].y
      ctx.beginPath()
      ctx.moveTo(bx, by)
      for (let k = 1; k < coordinates.length; k++) {
         let x = coordinates[k].x
         let y = coordinates[k].y
         ctx.lineTo(x, y)
      }
      ctx.fill()
      ctx.closePath()
      coordinates = []
      // coordinates.splice(0)
      console.log(list)
      // if (!isDrawingCompleted) {
      //    isDrawingCompleted = true
      // }
      // console.log(isDrawingCompleted);

      callback();
   }

   // 鼠标右键
   cav.oncontextmenu = e => {
      e.preventDefault()
      coordinates = []
      // coordinates.splice(0)
      isdraw = false
      endtip = true
      clear_now_line(list, ctx)
   }

   // 键盘事件(删除区域)
   cav.onkeydown = k => {
      let key = k.keyCode || k.which
      if ([8, 46].includes(key)) {
         if (!is_select) return Message.warning('请先点击某个区域为选中状态，再删除')
         list.splice(target_index, 1)
         ctx.clearRect(0, 0, 800, 600)
         if (list.length != 0) {
            draw_all_lines(list, ctx)
            draw_all_circles(list, ctx)
            fillarea(list, ctx)
         } else {
            ctx.clearRect(0, 0, 800, 600)
         }
         // isDrawingCompleted = false
      }
   }
}

function handleCanvasClick(event,list) {
   // 获取点击的坐标
   const mouseX = event.offsetX;
   const mouseY = event.offsetY;

   // 遍历所有图形并检查是否点击删除图标
   for (let i = 0; i < list.length; i++) {
      let cors = list[i];

      // 找到最右上角的点 (右上角的点就是删除图标的参考点)
      let maxXPoint = cors[0];
      for (let j = 1; j < cors.length; j++) {
         if (cors[j].x > maxXPoint.x) {
            maxXPoint = cors[j];
         } else if (cors[j].x === maxXPoint.x && cors[j].y < maxXPoint.y) {
            maxXPoint = cors[j];
         }
      }

      // 删除图标的区域
      let deleteIconSize = 20;
      let deleteX = maxXPoint.x + 5;
      let deleteY = maxXPoint.y - 5;

      // 判断是否点击在删除图标区域
      if (mouseX >= deleteX && mouseX <= deleteX + deleteIconSize && mouseY >= deleteY - deleteIconSize && mouseY <= deleteY) {
         // 删除图形
         list.splice(i, 1); // 从图形数组中删除当前图形
         draw_all_lines(list, ctx); // 重新绘制画布
         break; // 删除后跳出循环，避免多次删除
      }
   }
}
//这里对移动图形函数进行的优化，使得移动图形的时候不能够移出图片区域
function move_draw(list, ctx, cav, index, sX, sY) {
   let mark = list[index];
   let handle_move = em => {
      let target_data = [];
      let newX = em.offsetX - sX;
      let newY = em.offsetY - sY;

      // 边界检查，确保图形不会移出canvas
      mark.forEach(item => {
         let calculatedX = item.x + newX;
         let calculatedY = item.y + newY;

         // 限制calculatedX和calculatedY在canvas范围内
         calculatedX = Math.max(0, Math.min(cav.width, calculatedX));
         calculatedY = Math.max(0, Math.min(cav.height, calculatedY));

         target_data.push({
            x: calculatedX,
            y: calculatedY,
         });
      });

      ctx.clearRect(0, 0, cav.width, cav.height); // 使用cav.width和cav.height而不是固定值
      list.splice(index, 1, target_data);
      draw_all_lines(list, ctx);
      draw_all_circles(list, ctx);
      fillarea(list, ctx, index);
   };

   let handle_up = e => {
      cav.removeEventListener('mousemove', handle_move);
      cav.removeEventListener('mouseup', handle_up);
   };

   // 移除监听器部分保持不变
   cav.removeEventListener('mousemove', handle_move) // 先移除监听
   cav.removeEventListener('mousemove', handle_move) // 先移除监听
   cav.removeEventListener('mouseup', handle_up) // 先移除监听
   cav.removeEventListener('mouseup', handle_up) // 先移除监听
   cav.removeEventListener('mousemove', handle_move) // 先移除监听
   cav.removeEventListener('mousemove', handle_move) // 先移除监听
   cav.removeEventListener('mouseup', handle_up) // 先移除监听
   cav.removeEventListener('mouseup', handle_up) // 先移除监听
   cav.addEventListener('mousemove', handle_move) // 再重新监听，解决点击多次移除不干净的bug
   cav.addEventListener('mouseup', handle_up) // 再重新监听，解决点击多次移除不干净的bug
}

/* 编辑多边形端点 */
function changeDraw(list, cav, ctx, index_list) {
   cav.style.cursor = 'pointer'
}

// 判断鼠标是否在端点
function findClosestPointIndex(list, points, type) {
   let closestIndex = []
   let closestDistance = Infinity
   for (let i = 0; i < list.length; i++) {
      for (let j = 0; j < list[i].length; j++) {
         let point = list[i][j]
         let diffX = Math.abs(points.x - point.x)
         let diffY = Math.abs(points.y - point.y)
         let distance = Math.sqrt(diffX * diffX + diffY * diffY)
         if (distance <= 2 && distance < closestDistance) {
            closestIndex = [i, j]
            closestDistance = distance
         }
      }
   }
   if (type == 'is') return closestIndex.length
   return closestIndex
}

// 清除当前未画完成的区域
function clear_now_line(list, ctx) {
   ctx.clearRect(0, 0, 800, 600)
   if (list.length != 0) {
      draw_all_lines(list, ctx)
      draw_all_circles(list, ctx)
      fillarea(list, ctx)
   }
}

// 绘制选中的,颜色填充
function fillarea(list, ctx, index) {
   for (var i = 0; i < list.length; i++) {
      var cors = list[i]
      var x0 = cors[0].x
      var y0 = cors[0].y
      ctx.beginPath()
      ctx.fillStyle = i == index ? 'rgba(255,0,0,0.1)' : 'transparent'
      ctx.moveTo(x0, y0)
      for (var j = 1; j < cors.length; j++) {
         var x = cors[j].x
         var y = cors[j].y
         ctx.lineTo(x, y)
      }
      ctx.fill()
      ctx.closePath()
   }
}

// 判断坐标点是否在区域内的函数
function isPointInPolygon(list, point) {
   let isInside = false
   // 射线与多边形边线的交点数量
   let intersections = 0
   for (let i = 0; i < list.length; i++) {
      let coordinate1 = list[i]
      let coordinate2 = list[(i + 1) % list.length]
      // 判断射线与边线是否相交
      if (
         coordinate1.y > point.y !== coordinate2.y > point.y &&
         point.x <
         ((coordinate2.x - coordinate1.x) * (point.y - coordinate1.y)) /
         (coordinate2.y - coordinate1.y) +
         coordinate1.x
      ) {
         intersections++
      }
   }
   // 判断点是否在多边形内
   if (intersections % 2 !== 0) {
      isInside = true
   }
   return isInside
}

// 把当前绘制的多边形之前的坐标线段绘制出来
function draw_now_line(coordinates, ctx) {
   for (let i = 0; i < coordinates.length - 1; i++) {
      ctx.beginPath()
      let x0 = coordinates[i].x
      let y0 = coordinates[i].y
      let x1 = coordinates[i + 1].x
      let y1 = coordinates[i + 1].y
      ctx.moveTo(x0, y0)
      ctx.lineTo(x1, y1)
      ctx.stroke()
      ctx.closePath()
   }
}

// 把当前绘制的多边形之前的端点画圆
function draw_now_circle(coordinates, ctx) {
   ctx.fillStyle = 'red'
   for (let i = 0; i < coordinates.length; i++) {
      let x = coordinates[i].x
      let y = coordinates[i].y
      ctx.beginPath() //起始一条路径，或重置当前路径
      ctx.moveTo(x, y) //把路径移动到画布中的指定点（x,y）开始坐标
      ctx.arc(x, y, 5, 0, Math.PI * 2) //点
      ctx.fill() //填充点
      ctx.closePath() //创建从当前点回到起始点的路径
   }
}

