function draw_all_lines(list, ctx) {
   for (let i = 0; i < list.length; i++) {
      let cors = list[i];
      
      // 设置颜色
      if (cors[0].color != null) {
         ctx.strokeStyle = cors[0].color;
      } else {
         ctx.strokeStyle = 'red';
      }

      // 找到最左上角的点
      let minXPoint = cors[0];
      for (let j = 1; j < cors.length; j++) {
         if (cors[j].x < minXPoint.x) {
            minXPoint = cors[j];
         } else if (cors[j].x === minXPoint.x && cors[j].y < minXPoint.y) {
            // 如果x坐标相同，则比较y坐标，以找到最靠上面的点
            minXPoint = cors[j];
         }
      }

      // 前后坐标连线
      for (let j = 0; j < cors.length - 1; j++) {
         ctx.beginPath();
         let x0 = cors[j].x;
         let y0 = cors[j].y;
         let x1 = cors[j + 1].x;
         let y1 = cors[j + 1].y;
         ctx.moveTo(x0, y0);
         ctx.lineTo(x1, y1);
         ctx.stroke();
         ctx.closePath();
      }

      // 最后一个与第一个连线
      let begin_x = cors[0].x;
      let begin_y = cors[0].y;
      let end_x = cors[cors.length - 1].x;
      let end_y = cors[cors.length - 1].y;
      ctx.fillStyle = 'transparent';
      ctx.beginPath();
      ctx.moveTo(begin_x, begin_y);
      ctx.lineTo(end_x, end_y);
      ctx.stroke();
      ctx.closePath();

      // 在最靠左点位标注type类型
      ctx.fillStyle = '#ffffff'; // 设置文字颜色
      ctx.font = '16px Arial'; // 设置字体样式和大小
      let type = minXPoint.type; // 使用最靠左的点来获取type信息
      ctx.fillText(type, minXPoint.x, minXPoint.y); // 在最靠左点位标注type类型

      // 找到右上角的点
      let maxXPoint = cors[0];
      for (let j = 1; j < cors.length; j++) {
         if (cors[j].x > maxXPoint.x) {
            maxXPoint = cors[j];
         } else if (cors[j].x === maxXPoint.x && cors[j].y < maxXPoint.y) {
            // 如果x坐标相同，则比较y坐标，以找到最靠上的点
            maxXPoint = cors[j];
         }
      }

      // 绘制删除图标（圆形背景加×）
      let deleteIconSize = 20; // 删除图标的大小
      let deleteX = maxXPoint.x + 5; // 删除图标的 X 坐标
      let deleteY = maxXPoint.y - 5; // 删除图标的 Y 坐标

      // 绘制圆形背景
      // ctx.beginPath();
      // ctx.arc(deleteX, deleteY, deleteIconSize / 2, 0, 2 * Math.PI);
      // ctx.fillStyle = "grey"; // 圆形背景颜色
      // ctx.fill();
      // ctx.closePath();

      // 绘制 "X" 删除图标
      // ctx.font = "bold 16px Arial"; // 设置字体
      ctx.fillStyle = cors[0].color; // 图标颜色（白色）
      ctx.textAlign = "center"; // 设置文本对齐方式
      ctx.textBaseline = "middle"; // 设置文本垂直居中
      ctx.fillText("🗑️", deleteX, deleteY); // 在圆形中间绘制 "×"
   }

   // 恢复默认颜色
   ctx.strokeStyle = 'red';
}


// 画出所有多边形的端点
function draw_all_circles(list, ctx, cav) {
   for (let i = 0; i < list.length; i++) {
      let cors = list[i]
      if (cors[0].color != null) {
         ctx.fillStyle = cors[0].color
      } else {
         ctx.fillStyle = 'red'
      }
      for (let j = 0; j < cors.length; j++) {
         let x = cors[j].x
         let y = cors[j].y
         ctx.beginPath()
         ctx.moveTo(x, y)
         ctx.arc(x, y, 4, 0, Math.PI * 2)
         ctx.fill()
         ctx.closePath()
      }
   }
   ctx.fillStyle = 'red'
}

// 判断直线是否相交
function judgeIntersect(x1, y1, x2, y2, x3, y3, x4, y4) {
   if (
      !(
         Math.min(x1, x2) <= Math.max(x3, x4) &&
         Math.min(y3, y4) <= Math.max(y1, y2) &&
         Math.min(x3, x4) <= Math.max(x1, x2) &&
         Math.min(y1, y2) <= Math.max(y3, y4)
      )
   )
      return false
   let u, v, w, z
   u = (x3 - x1) * (y2 - y1) - (x2 - x1) * (y3 - y1)
   v = (x4 - x1) * (y2 - y1) - (x2 - x1) * (y4 - y1)
   w = (x1 - x3) * (y4 - y3) - (x4 - x3) * (y1 - y3)
   z = (x2 - x3) * (y4 - y3) - (x4 - x3) * (y2 - y3)
   return u * v <= 0.00000001 && w * z <= 0.00000001
}